head.script:
scwin.selectCallback = function(fileArr) {
    if (fileArr.length === 0) {
        return;
    }
    var uploadFiles = [];
    var dataList_name = "";
    var dataList_size = "";
    if (dataList1.getRowCount() + fileArr.length > h5_trans.options.maxcount) {
        alert("[selectCallback] 업로드건수가 " + h5_trans.options.maxcount + "건으로 제한되어 있습니다.");
        for (var i = 0, len = fileArr.length; i < len; i++) {
            h5_trans.removeFile(fileArr[i].name);
        }
        return;
    };
    for (var i = 0; i < fileArr.length; i++) {
        var isAdded = false;
        var isExist = false;
        var file_name = fileArr[i].name;
        var file_size = fileArr[i].size;
        for (var j = 0; j < dataList1.getRowCount(); j++) {
            dataList_name = dataList1.getCellData(j, "name");
            dataList_size = dataList1.getCellData(j, "size");
            if (dataList_name == file_name && dataList_size == file_size) {
                isExist = true;
                break;
            }
        }
        if (isExist) {
            alert("[HTML5 selectCallback] 파일이 이미 있습니다. (" + file_name + ")");
            h5_trans.removeFile(file_name);
        } else {
            var obj = {
                name: file_name,
                size: file_size
            };
            uploadFiles.push(obj);
        }
    }
    dataList1.insertJSON(dataList1.getRowCount(), uploadFiles);
};
scwin.flashSelectCallback = function(fileArr) {
    debugger;
    if (fileArr.length === 0) {
        return;
    }
    var uploadFiles = [];
    var dataList_name = "";
    var dataList_size = "";
    if (dataList1.getRowCount() + fileArr.length > flash_trans.options.maxcount) {
        alert("[selectCallback] 업로드건수가 " + flash_trans.options.maxcount + "건으로 제한되어 있습니다.");
        for (var i = 0, len = fileArr.length; i < len; i++) {
            flash_trans.removeFile(fileArr[i].name);
        }
        return;
    };
    for (var i = 0; i < fileArr.length; i++) {
        var isAdded = false;
        var isExist = false;
        var file_name = fileArr[i].name;
        var file_size = fileArr[i].size;
        for (var j = 0; j < dataList1.getRowCount(); j++) {
            dataList_name = dataList1.getCellData(j, "name");
            dataList_size = dataList1.getCellData(j, "size");
            if (dataList_name == file_name && dataList_size == file_size) {
                isExist = true;
                break;
            }
        }
        if (isExist) {
            alert("[flash selectCallback] 파일이 이미 있습니다. (" + file_name + ")");
            flash_trans.removeFile(file_name);
        } else {
            var obj = {
                name: file_name,
                size: file_size
            };
            uploadFiles.push(obj);
        }
    }
    dataList1.insertJSON(dataList1.getRowCount(), uploadFiles);
};
scwin.multi1_onComplete = function() {
    console.log("onComplete10");
};
scwin.multiupload10_ondone = function(data) {
    console.log("multiupload10_ondone");
    console.log(data);
    var cnt = dataList1.getRowCount();
    for (var i = 0; i < cnt; i++) {
        dataList1.setCellData(i, 3, "Complete!!!!");
    }
    setTimeout(scwin.clearUpload, "1000");
};
scwin.clearUpload = function() {
    dataList1.removeAll();
};
scwin.textbox4_onclick = function(e) {
    var idxArr = gridView1.getCheckedJSON("chk");
    var idxArr1 = gridView1.getCheckedIndex("chk");
    for (var i = 0; i < idxArr.length; i++) {
        var fileName = idxArr[i].name;
        h5_trans.removeFile(fileName);
        dataList1.removeRow(idxArr1[i]);
    }
};
scwin.textbox5_onclick = function(e) {
    h5_trans.startUpload();
    var cnt = dataList1.getRowCount();
    for (var i = 0; i < cnt; i++) {
        dataList1.setCellData(i, 3, "Uploading...");
    }
};
scwin.flash_trans_onerror = function(err) {
    console.log(err);
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
